<?php
namespace MarinePortal\Core;
class Router { private array $config; public function __construct(array $config){ $this->config=$config; } public function dispatch(): void { $uri = parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH); $uri = rtrim($uri,'/') ?: '/'; if (str_starts_with($uri,'/install')) { require ROOT.'/install/index.php'; return; } if ($uri==='/auth/login') { (new \MarinePortal\Auth\Auth0Controller($this->config))->login(); return; } if ($uri==='/auth/callback') { (new \MarinePortal\Auth\Auth0Controller($this->config))->callback(); return; } if ($uri==='/auth/logout') { (new \MarinePortal\Auth\Auth0Controller($this->config))->logout(); return; } $auth = new \MarinePortal\Auth\AuthGuard($this->config); if (!$auth->check()) { header('Location: /auth/login'); exit; } if ($uri==='/') { echo "<h1>".htmlspecialchars($this->config['app']['name'])."</h1><p>Welcome ".$_SESSION['user']['email']." | <a href='/admin'>Admin</a> | <a href='/auth/logout'>Logout</a></p>"; return; } if ($uri==='/admin') { $guard=new \MarinePortal\Auth\AuthGuard($this->config); if(!$guard->isAdmin()) { http_response_code(403); echo "Admin only"; exit; } echo file_get_contents(ROOT.'/src/Views/admin.html'); return; } http_response_code(404); echo "404"; } }
